import { NextRequest, NextResponse } from "next/server";
import { requireAuth } from "@/lib/require-auth";
import { getDb } from "@/lib/mongodb";
import { ObjectId } from "mongodb";
import { signToken } from "@/lib/auth";

export async function POST(request: NextRequest) {
  const auth = requireAuth(request);
  if (auth.error) return auth.error;

  try {
    const { quotationId } = await request.json();
    if (!quotationId) {
      return NextResponse.json({ error: "quotationId required" }, { status: 400 });
    }

    // Verify quotation exists
    const db = await getDb();
    let quotation: any = null;
    try {
      quotation = await db.collection("quotations").findOne({ _id: new ObjectId(quotationId) });
    } catch {
      quotation = await db.collection("quotations").findOne({ _id: quotationId as any });
    }
    if (!quotation) {
      return NextResponse.json({ error: "Quotation not found" }, { status: 404 });
    }

    // Generate a short-lived token so Puppeteer can authenticate as the same user
    const puppeteerToken = signToken(
      { id: auth.decoded.id, email: auth.decoded.email, role: auth.decoded.role },
      { expiresIn: "5m" }
    );

    const origin = request.nextUrl.origin;
    const viewUrl = `${origin}/quotations/${quotationId}/view`;

    const puppeteer = await import("puppeteer");
    const browser = await puppeteer.default.launch({
      headless: true,
      args: ["--no-sandbox", "--disable-setuid-sandbox", "--disable-dev-shm-usage"],
    });

    try {
      const page = await browser.newPage();

      // Set viewport to A4 width at 96dpi
      await page.setViewport({ width: 794, height: 1122 });

      // Navigate first to set localStorage on the correct origin
      await page.goto(origin, { waitUntil: "domcontentloaded", timeout: 10000 }).catch(() => {});
      await page.evaluate((token: string) => {
        localStorage.setItem("auth_token", token);
      }, puppeteerToken);

      // Now navigate to the actual view page
      await page.goto(viewUrl, { waitUntil: "networkidle0", timeout: 30000 });

      // Wait for the quotation content to render (no loading spinner visible)
      await page.waitForFunction(
        () => !document.body.innerText.includes("Loading quotation"),
        { timeout: 15000 }
      ).catch(() => {});

      // Small buffer for images/fonts to finish
      await new Promise((r) => setTimeout(r, 1500));

      await page.emulateMediaType("print");

      const pdfBuffer = await page.pdf({
        format: "A4",
        printBackground: true,
        margin: { top: 0, bottom: 0, left: 0, right: 0 },
      });

      const safeTitle = ((quotation.title || "Quotation") as string).replace(/[^a-zA-Z0-9-_]/g, "-");
      const filename = `${quotation.quoteId || quotationId}-${safeTitle}.pdf`;

      return new NextResponse(pdfBuffer, {
        status: 200,
        headers: {
          "Content-Type": "application/pdf",
          "Content-Disposition": `attachment; filename="${filename}"`,
          "X-Filename": filename,
        },
      });
    } finally {
      await browser.close();
    }
  } catch (e: any) {
    console.error("generate-quotation-pdf error:", e);
    return NextResponse.json({ error: e.message || "PDF generation failed" }, { status: 500 });
  }
}
